"use client";

import { useState, useEffect } from "react";
import { useFinanceData, useSubmit } from "@/lib/api";
import TransactionForm from "@/components/finance/TransactionForm";
import Empty from "@/components/finance/Empty";
import TransactionTable from "@/components/finance/TransactionTable";
import CategoryBreakdown from "@/components/finance/CategoryBreakdown";
import MonthlyTrend from "@/components/finance/MonthlyTrend";
import RecurringList from "@/components/finance/RecurringList";
import InsightsPanel from "@/components/finance/InsightsPanel";

const TrackerPage = () => {
  const [filter, setFilter] = useState({ dateRange: null, category: null, account: null });
  const { data: transactions, isLoading, error } = useFinanceData("/tracker/transactions", filter);
  const submit = useSubmit();

  if (isLoading) return <Empty />;
  if (error) return <Empty />;

  return (
    <div>
      <TransactionForm onSubmit={submit} />
      <TransactionTable data={transactions} onSubmit={submit} />
      <CategoryBreakdown data={transactions} />
      <MonthlyTrend data={transactions} />
      <RecurringList data={transactions} />
      <InsightsPanel data={transactions} />
    </div>
  );
};

export default TrackerPage;
